  channel.onmessage = async () => {
    try {
      const response = await fetch("/api/data", {cache:"no-store"});
      const result = await response.json();
      if (response.ok && Array.isArray(result.data)) {
        setStudents(result.data as Student[]);
        saveStudents(result.data as Student[]);
      }
    } catch {}
  };
  return () => channel.close();
}, []);
useEffect(() => {
  let cancelled=false;

  const refresh=async()=>{
    try{
      const response=await fetch("/api/notes",{cache:"no-store"});
      const result=await response.json().catch(()=>({}));
      if(!response.ok||!result.ok){
        throw new Error(result.error||"Falha ao carregar recados do Todoist.");
      }
      if(cancelled)return;
      setNotes(Array.isArray(result.data)?result.data:[]);
      setNotesError(String(result.google?.warning||""));
    }catch(error){
      if(cancelled)return;
      console.error("Erro ao carregar recados do Todoist:",error);
      setNotesError(error instanceof Error?error.message:"Falha ao carregar recados do Todoist.");
    }
  };

  const onFocus=()=>{void refresh();};
  const onVisibility=()=>{
    if(document.visibilityState==="visible")void refresh();
  };

  void refresh();
  window.addEventListener("focus",onFocus);
  document.addEventListener("visibilitychange",onVisibility);
  const timer=window.setInterval(()=>{
    if(document.visibilityState==="visible")void refresh();
  },30000);

  return()=>{
    cancelled=true;
    window.removeEventListener("focus",onFocus);
    document.removeEventListener("visibilitychange",onVisibility);
    window.clearInterval(timer);
  };
},[]);

useEffect(()=>{
  if(view!=="today")return;
  let cancelled=false;

  const loadHomePerformance=async()=>{
    try{
      const response=await fetch("/api/performance",{cache:"no-store"});
      const result=await response.json();
      const activities:PerformanceActivity[]=result?.data?.activities||[];

      if(!cancelled){
        setHomePerformanceActivities(activities);
        setTodayPerformanceActivities(
          activities
            .filter(activity=>activity.date===today())
            .sort((a,b)=>(b.createdAt||"").localeCompare(a.createdAt||""))
        );
      }
    }catch{
      if(!cancelled){setTodayPerformanceActivities([]);setHomePerformanceActivities([]);}
    }
  };

  void loadHomePerformance();
  return()=>{cancelled=true;};
},[view]);

useEffect(()=>{
