const assert=require('node:assert/strict');
const {applyFinanceCommand:apply}=require('../.operational-tests/lib/financeiro/operacoes');
const {financeSummary}=require('../.operational-tests/lib/financeiro/calculos');
const {parseGalileuStructuredText:parse}=require('../.operational-tests/lib/assessments/text-import');
const {importPerformanceAssessment:importText,PERFORMANCE_COMPOSITION_FIELDS:fields}=require('../.operational-tests/lib/assessments/performance-fields');
const {workoutPageTitle:title}=require('../.operational-tests/lib/workout-page-title');
const Actions=require('../.operational-tests/components/HomeStudentActions').default;
const React=require('react'),{renderToStaticMarkup}=require('react-dom/server');
let count=0;function test(name,fn){fn();console.log('OK '+(++count)+' '+name);}
const base=()=>({version:1,currentCompetence:'2026-09',competences:{'2026-09':{status:'OPEN'}},dsPercent:50,rankingByCompetence:{},personalInvoices:[],dsKids:[],dsReceipts:{},expenses:[],extraExpenses:[],categories:[],history:[]});
const create=(data,extra={})=>apply(data,{type:'EXPENSE_CREATE',competence:'2026-09',startCompetence:'2026-10',name:'Conta',dueDay:10,expectedAmount:100,kind:'RECURRING',...extra});
const next=(data,month)=>apply(data,{type:'CREATE_NEXT_COMPETENCE',fromCompetence:month});
test('início outubro sem lançamento em setembro',()=>{const d=create(base());assert.equal(d.expenses[0].competence,'2026-10');assert.equal(d.expenses[0].dueDay,10);assert.equal(d.currentCompetence,'2026-10');});
test('outros recorrentes renovados ao abrir início futuro',()=>{let b=create(base(),{startCompetence:'2026-09',name:'Anterior'});let d=create(b);assert.equal(d.expenses.filter(e=>e.name==='Anterior').length,2);});
test('parcelas avançam e terminam',()=>{let d=create(base(),{kind:'INSTALLMENT',installmentCurrent:1,installmentTotal:2});d=next(d,'2026-10');assert.equal(d.expenses.at(-1).installmentCurrent,2);assert.equal(next(d,'2026-11').expenses.length,2);});
test('datas e parcelas inválidas rejeitadas',()=>{for(const x of [{startCompetence:'2026-13'},{dueDay:0},{kind:'INSTALLMENT',installmentCurrent:3,installmentTotal:2}]){const b=base();assert.equal(create(b,x),b);}});
test('competência fechada preservada',()=>{const b=base();b.competences['2026-10']={status:'CLOSED'};assert.equal(create(b),b);});
test('excluir só ocorrência mantém renovação',()=>{let d=create(base());let e=d.expenses[0];d=apply(d,{type:'EXPENSE_DELETE',id:e.id,scope:'CURRENT'});assert.equal(d.expenses.length,0);d=next(d,'2026-10');assert.equal(d.expenses.length,1);assert.equal(d.expenses[0].competence,'2026-11');assert.equal(d.expenses[0].seriesId,e.seriesId);});
test('exclusão de parcela mantém progressão',()=>{let d=create(base(),{kind:'INSTALLMENT',installmentCurrent:1,installmentTotal:2});d=apply(d,{type:'EXPENSE_DELETE',id:d.expenses[0].id});assert.equal(next(d,'2026-10').expenses[0].installmentCurrent,2);});
test('série excluída não retorna',()=>{let d=create(base());let id=d.expenses[0].id;d=next(d,'2026-10');d=apply(d,{type:'EXPENSE_DELETE',id,scope:'CURRENT_AND_FUTURE'});assert.equal(d.expenses.length,0);assert.equal(next(d,'2026-11').expenses.length,0);assert.ok(d.history.length);});
test('pagamentos e meses fechados protegidos na série',()=>{let d=create(base());let id=d.expenses[0].id;d=next(d,'2026-10');d=next(d,'2026-11');d.expenses[1].payments=[{id:'p',date:'2026-11-10',amount:100}];d.competences['2026-12'].status='CLOSED';let saved=JSON.stringify(d.expenses.slice(1));d=apply(d,{type:'EXPENSE_DELETE',id,scope:'CURRENT_AND_FUTURE'});assert.equal(JSON.stringify(d.expenses),saved);});
test('ocorrência paga não excluída',()=>{let d=create(base());d.expenses[0].payments=[{id:'p',amount:10}];assert.equal(apply(d,{type:'EXPENSE_DELETE',id:d.expenses[0].id}),d);});
test('contas com mesmo nome não misturadas',()=>{let d=create(create(base()));const keep=d.expenses[1].id;d=apply(d,{type:'EXPENSE_DELETE',id:d.expenses[0].id,scope:'CURRENT_AND_FUTURE'});assert.equal(d.expenses[0].id,keep);});
test('legado sem vínculo rejeita exclusão em série',()=>{let d=create(base());delete d.expenses[0].seriesId;delete d.expenses[0].startCompetence;assert.equal(apply(d,{type:'EXPENSE_DELETE',id:d.expenses[0].id,scope:'CURRENT_AND_FUTURE'}),d);});
test('legado recebe vínculo só na nova renovação',()=>{let d=create(base());delete d.expenses[0].seriesId;const original=JSON.stringify(d.expenses[0]);let n=next(d,'2026-10');assert.equal(JSON.stringify(n.expenses[0]),original);assert.equal(n.expenses[1].seriesId,d.expenses[0].id);});
test('metadados sobrevivem armazenamento JSON',()=>{let d=create(base());d=apply(d,{type:'EXPENSE_DELETE',id:d.expenses[0].id});d=JSON.parse(JSON.stringify(d));assert.equal(next(d,'2026-10').expenses.length,1);});
test('devolução parcial reduz dívida DS sem quitar o restante',()=>{let d=base();d.dsPercent=.5;d.dsKids=[{id:'k',competence:'2026-09',studentId:'s',studentName:'Kids',amount:200}];d.dsReceipts={'2026-09':[{id:'r',date:'2026-09-30',amount:300}]};assert.equal(financeSummary(d).dsBalance,-200);d=apply(d,{type:'DS_RETURN_ADD',competence:'2026-09',date:'2026-09-30',amount:80,note:'parcial'});const s=financeSummary(d);assert.equal(s.dsReturned,80);assert.equal(s.dsBalance,-120);});
test('saldo DS devedor passa ao mês seguinte e abate novo acerto',()=>{let d=base();d.dsPercent=.5;d.dsKids=[{id:'k',competence:'2026-09',studentId:'s',studentName:'Kids',amount:200,billingMode:'RECURRING'}];d.dsReceipts={'2026-09':[{id:'r',date:'2026-09-30',amount:300}]};d=apply(d,{type:'DS_RETURN_ADD',competence:'2026-09',date:'2026-09-30',amount:80});d=next(d,'2026-09');assert.equal(d.dsOpeningBalances['2026-10'],-120);assert.equal(financeSummary(d,'2026-10').dsBalance,-20);});
test('devolução total zera dívida DS',()=>{let d=base();d.dsReceipts={'2026-09':[{id:'r',date:'2026-09-30',amount:100}]};d=apply(d,{type:'DS_RETURN_ADD',competence:'2026-09',date:'2026-09-30',amount:100});assert.equal(financeSummary(d).dsBalance,0);});
test('saldo anterior DS pode ser corrigido com histórico preservado',()=>{let d=base();d.dsOpeningBalances={'2026-09':-120};d=apply(d,{type:'DS_OPENING_BALANCE_SET',competence:'2026-09',balance:-75,note:'acerto conferido'});assert.equal(financeSummary(d).dsOpeningBalance,-75);assert.equal(financeSummary(d).dsBalance,-75);assert.equal(d.history.at(-1).kind,'DS_OPENING_BALANCE_UPDATED');assert.match(d.history.at(-1).description,/120\.00.*75\.00.*acerto conferido/);});
test('eventos entram no acerto DS e iniciam zerados no próximo mês',()=>{let d=base();d=apply(d,{type:'EVENTS_SET',competence:'2026-09',amount:900});assert.equal(financeSummary(d).events,900);assert.equal(financeSummary(d).dsSettlement,900);d=next(d,'2026-09');assert.equal(financeSummary(d,'2026-10').events,0);assert.equal(d.dsOpeningBalances['2026-10'],900);});
const text='Data: 30/09/2026\nPeso: 81,2\nAltura: 178\nIMC: 25,6\nGordura corporal: 18,4\nMassa de gordura: 14,9\nMassa magra kg: 66,3\nMassa magra %: 81,6\nÁgua corporal %: 59,1\nÁgua corporal total: 48\nÍndice de hidratação: 3,2\nÁgua na massa magra: 72,4\nÁgua intracelular L: 29\nÁgua extracelular L: 19\nÁgua intracelular %: 60,4\nMassa muscular kg: 35\nMassa muscular %: 43,1\nRelação músculo/gordura: 2,3\nTMB: 1800\nÂngulo de fase: 6,1\nIdade celular: 32';
test('mesmo parser completo mapeia todos os campos Performance',()=>{const p=parse(text),v=importText(text);assert.equal(Object.values(p).filter(x=>x!==undefined).length,21);assert.equal(v.weightKg,'81.2');assert.equal(v.muscleMassKg,'35');assert.equal(v.date,'2026-09-30');for(const [key] of fields)assert.equal(v[key],String(Math.round(p[key]*10)/10));});
test('importação não inventa campos ausentes',()=>assert.deepEqual(importText('Peso: 72,5'),{weightKg:'72.5'}));
test('campos numéricos importados sobrevivem salvar/reabrir JSON',()=>{let v=importText(text);let saved=JSON.parse(JSON.stringify(Object.fromEntries(Object.entries(v).map(([k,x])=>[k,k==='date'?x:Number(x)]))));assert.equal(saved.phaseAngle,6.1);assert.equal(saved.waterPercent,59.1);});
test('títulos de treino e restauração',()=>{for(const view of ['workout-editor','planned-session','historical-workout','free-session'])assert.equal(title(view,'summary','Ana'),'Treino — Ana');assert.equal(title('student','workouts','Bia'),'Treino — Bia');assert.equal(title('today','workouts','Ana'),'DMP - Danilo Modesto Personal');assert.equal(title('planned-session','summary'),'DMP - Danilo Modesto Personal');});
test('quatro botões pendentes preservam o layout antigo e callbacks',()=>{let calls=[];let el=Actions({settled:false,onHistory:()=>calls.push('h'),onRegister:()=>calls.push('r'),onPresence:()=>calls.push('p'),onAbsence:()=>calls.push('a')});const children=el.props.children;assert.equal(children[0].props.children,'Histórico');assert.equal(children[0].props.className.includes('home-workouts-open'),true);assert.deepEqual(children[1].props.children.map(e=>e.props.children),['Registrar','Presença','Ausência']);children[0].props.onClick();children[1].props.children.forEach(e=>e.props.onClick());assert.deepEqual(calls,['h','r','p','a']);});
test('aluno finalizado ou ausente não exibe atalhos',()=>{const html=renderToStaticMarkup(React.createElement(Actions,{settled:true}));assert.equal((html.match(/<button/g)||[]).length,0);});
const {initializeDsOpeningBalances:initialize}=require('../.operational-tests/lib/financeiro/operacoes');
const {normalizeFinanceData:normalize,hasPendingDsOpeningInitialization:pending}=require('../.operational-tests/lib/financeiro/storage');
const {DsOpeningBalanceRow:OpeningRow,DsOpeningBalanceEditButton:OpeningButton}=require('../.operational-tests/components/financeiro/DsOpeningBalance');
const reload=d=>normalize(JSON.parse(JSON.stringify(d)),base());
test('saldo positivo transportado para novembro',()=>{let d=base();d.currentCompetence='2026-10';d.competences={'2026-10':{status:'OPEN'}};d.dsOpeningBalances={'2026-10':500};assert.equal(next(d,'2026-10').dsOpeningBalances['2026-11'],500);});
test('saldo negativo transportado para novembro',()=>{let d=base();d.currentCompetence='2026-10';d.competences={'2026-10':{status:'OPEN'}};d.dsOpeningBalances={'2026-10':-700};assert.equal(next(d,'2026-10').dsOpeningBalances['2026-11'],-700);});
const october=()=>{let d=base();d.currentCompetence='2026-10';d.competences['2026-10']={status:'OPEN'};return d;};
test('backfill autorizado outubro e resultado exato 11183.20',()=>{let d=october();d.dsPercent=.48;d.dsKids=[{id:'kid',studentId:'s',competence:'2026-10',amount:12072.01}];d.rankingByCompetence={'2026-10':5000};d.eventsByCompetence={'2026-10':2000};d=reload(d);assert.equal(d.dsOpeningBalances['2026-10'],-1611.36);assert.equal(financeSummary(d).dsSettlement,12794.56);assert.equal(financeSummary(d).dsBalance,11183.20);assert.equal(pending(d),true);});
test('transporte e recarga não duplicam saldo ou auditoria',()=>{let d=reload(october());const history=JSON.stringify(d.history);for(let i=0;i<3;i++)d=reload(d);assert.equal(d.dsOpeningBalances['2026-10'],-1611.36);assert.equal(JSON.stringify(d.history),history);assert.equal(pending(d),false);});
test('saldo explícito zero respeitado no backfill',()=>{let d=october();d.dsOpeningBalances={'2026-10':0};assert.equal(reload(d).dsOpeningBalances['2026-10'],0);});
test('correção manual substitui transportado e sobrevive recarga',()=>{let d=reload(october());d=apply(d,{type:'DS_OPENING_BALANCE_SET',competence:'2026-10',balance:-1500,note:'ajuste com DS'});assert.equal(reload(d).dsOpeningBalances['2026-10'],-1500);});
test('correção manual para zero é permanente',()=>{let d=reload(october());d=apply(d,{type:'DS_OPENING_BALANCE_SET',competence:'2026-10',balance:0,note:'quitado'});for(let i=0;i<3;i++)d=reload(d);assert.equal(d.dsOpeningBalances['2026-10'],0);});
test('zero pode virar a receber ou a devolver',()=>{for(const balance of [500,-500]){let d=october();d.dsOpeningBalances={'2026-10':0};d=apply(d,{type:'DS_OPENING_BALANCE_SET',competence:'2026-10',balance,note:'direção conferida'});assert.equal(reload(d).dsOpeningBalances['2026-10'],balance);}});
test('motivo vazio e valor não finito bloqueados no comando',()=>{const d=october();assert.equal(apply(d,{type:'DS_OPENING_BALANCE_SET',competence:'2026-10',balance:100,note:'  '}),d);assert.equal(apply(d,{type:'DS_OPENING_BALANCE_SET',competence:'2026-10',balance:NaN,note:'teste'}),d);});
