function endpointHarness(authorized=true,failFinance=false){
 let {data,state}=fixture();let snapshot,queries=0;const revision='2026-10-08T18:00:00.000Z';
 const query=async(sql,args=[])=>{queries++;if(sql==='BEGIN'){snapshot={data:structuredClone(data),state:structuredClone(state)};return {rows:[]};}if(sql==='ROLLBACK'){if(snapshot){data=snapshot.data;state=snapshot.state;}return {rows:[]};}if(sql==='COMMIT')return {rows:[]};if(sql.includes('ANY'))return {rows:[{id:'finance_v1',payload:data},{id:'mercado_pago_reconciliation_v1',payload:state}]};if(sql.startsWith('SELECT'))return {rows:[{payload:structuredClone(args[0]==='finance_v1'?data:state),updated_at:revision}]};if(sql.startsWith('UPDATE')){if(args[0]==='finance_v1'){if(failFinance)throw new Error('storage failed');data=JSON.parse(args[1]);}else state=JSON.parse(args[1]);}return {rows:[]};};
 const api=compile(read('app/api/finance/pix-payer/route.ts'),{'@/lib/auth':{isAuthorized:async()=>authorized},'@/lib/db':{pool:{query,connect:async()=>({query,release(){}})}},'@/lib/financeiro/pix-payer-edit':{compatiblePixRecords,editPixPayer},'next/server':{NextResponse:{json:(value,options)=>({value,status:options?.status||200})}}});
 return {api,request(name='Novo',expected='',version=revision){return {json:async()=>({fingerprint:'f1',payerName:name,expectedName:expected}),headers:{get:()=>version}};},get data(){return data;},get state(){return state;},get queries(){return queries;}};
}
